'use strict';

// MODULES //

var Float64Array = require( '@stdlib/array/float64' );
var Uint8Array = require( '@stdlib/array/uint8' );
var max = require( '@stdlib/math/base/special/fast/max' );


// MAIN //

/**
* Creates a strided matrix whose buffer elements are provided by a function.
*
* ## Notes
*
* -   The function `getValue` is invoked once for every buffer element. For elements belonging to the matrix, the function is provided the row index, the column index, and the buffer index. For all other elements (i.e., leading elements, trailing elements, and leading-dimension padding), the function is provided `-1`, `-1`, and the buffer index.
* -   When a stride is negated, the offset is adjusted such that the offset continues to point to the element having row and column indices equal to zero.
*
* @private
* @param {NonNegativeInteger} rows - number of rows
* @param {NonNegativeInteger} cols - number of columns
* @param {Object} opts - options
* @param {string} opts.order - storage layout (either `'row-major'` or `'column-major'`)
* @param {NonNegativeInteger} opts.pad - number of padding elements per leading dimension
* @param {NonNegativeInteger} opts.offset - number of buffer elements preceding the stored elements
* @param {NonNegativeInteger} opts.tail - number of buffer elements following the stored elements
* @param {boolean} opts.flip1 - boolean indicating whether to negate the stride of the first dimension
* @param {boolean} opts.flip2 - boolean indicating whether to negate the stride of the second dimension
* @param {Function} getValue - function returning element values
* @returns {Object} matrix description containing a buffer (`buf`), strides (`s1` and `s2`), an offset (`o`), and a mask identifying the buffer elements which belong to the matrix (`mask`)
*/
function createMatrix( rows, cols, opts, getValue ) {
	var mask;
	var buf;
	var len;
	var idx;
	var s1;
	var s2;
	var o;
	var i;
	var j;

	if ( opts.order === 'row-major' ) {
		s1 = max( cols, 1 ) + opts.pad;
		s2 = 1;
	} else {
		s1 = 1;
		s2 = max( rows, 1 ) + opts.pad;
	}
	o = opts.offset;
	len = o + ( max( rows-1, 0 )*s1 ) + ( max( cols-1, 0 )*s2 ) + 1 + opts.tail;
	if ( opts.flip1 ) {
		o += max( rows-1, 0 ) * s1;
		s1 *= -1;
	}
	if ( opts.flip2 ) {
		o += max( cols-1, 0 ) * s2;
		s2 *= -1;
	}
	buf = new Float64Array( len );
	mask = new Uint8Array( len );
	for ( i = 0; i < rows; i++ ) {
		for ( j = 0; j < cols; j++ ) {
			mask[ o+(i*s1)+(j*s2) ] = 1;
		}
	}
	for ( idx = 0; idx < len; idx++ ) {
		if ( mask[ idx ] === 0 ) {
			buf[ idx ] = getValue( -1, -1, idx );
		}
	}
	for ( i = 0; i < rows; i++ ) {
		for ( j = 0; j < cols; j++ ) {
			idx = o + ( i*s1 ) + ( j*s2 );
			buf[ idx ] = getValue( i, j, idx );
		}
	}
	return {
		'buf': buf,
		's1': s1,
		's2': s2,
		'o': o,
		'mask': mask
	};
}


// EXPORTS //

module.exports = createMatrix;
